pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount, uint256 depositAmount) public {
        // Bound parameters to avoid overflow and ensure meaningful scenarios
        amount = bound(amount, 0, 1e30);
        depositAmount = bound(depositAmount, 1 ether, 1e30);
        vm.assume(caller != address(0)); // avoid zero address issues

        // First, deposit some ether to the caller to have balance
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balances before CashOut
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 zeroBalanceBefore = c.balances(address(0));

        // Perform CashOut, which may revert due to insufficient balance
        vm.prank(caller);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSignature("CashOut(uint256)", amount));

        // If CashOut succeeded
        if (success) {
            uint256 callerBalanceAfter = c.balances(caller);
            uint256 zeroBalanceAfter = c.balances(address(0));
            // The sum of caller's balance and zero address balance should decrease by exactly the amount withdrawn (ether sent out), because in reference C, zero balance unchanged and caller balance decreases by amount.
            // In buggy version, zero balance increases, so sum changes differently.
            // Specifically: (callerBalanceAfter + zeroBalanceAfter) = (callerBalanceBefore + zeroBalanceBefore) - amount
            assertTrue(callerBalanceAfter + zeroBalanceAfter == callerBalanceBefore + zeroBalanceBefore - amount, "Sum invariant violated");
        } else {
            // If reverted, balances unchanged
            assertTrue(c.balances(caller) == callerBalanceBefore, "Balance changed on revert");
            assertTrue(c.balances(address(0)) == zeroBalanceBefore, "Zero balance changed on revert");
        }
    }
}

