contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 deposit, uint256 withdraw) public {
        // Bound inputs to realistic ranges
        deposit = bound(deposit, 1 ether, 1000 ether);
        withdraw = bound(withdraw, 0, deposit);

        // Give caller ether and deposit
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Record balances before CashOut
        uint256 callerBalBefore = c.balances(caller);
        uint256 zeroBalBefore = c.balances(address(0));

        // Call CashOut
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, withdraw));

        // Only consider non-reverting calls
        vm.assume(success);

        uint256 callerBalAfter = c.balances(caller);
        uint256 zeroBalAfter = c.balances(address(0));

        // The rule: caller's decrease plus zero's increase equals withdrawn amount
        assertTrue(callerBalBefore - callerBalAfter + (zeroBalAfter - zeroBalBefore) == withdraw);
    }
