pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Track initial total supply
    uint256 initialTotalSupply;

    function setUp() public {
        c = new C(address(this));
        // Fund contract with some initial balance for realistic fuzzing (optional)
        vm.deal(address(c), 100 ether);
    }

    function testFuzz_property(address caller, uint256 depositAmt, uint256 cashOutAmt, uint256 supplyOffset) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        uint256 deposit = bound(depositAmt, 1 ether, 10 ether);
        uint256 cashOut = bound(cashOutAmt, 0, 5 ether);
        uint256 offset = bound(supplyOffset, 0, 100 ether);

        // Step 1: Set up initial state by performing a deposit from caller
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Step 2: Perform a deposit from another account to have multiple balances
        address dummy = address(0x1234);
        vm.deal(dummy, offset);
        vm.prank(dummy);
        c.Deposit{value: offset}();

        // Compute current total supply (sum of all balances) + contract ether balance
        // We need to iterate over all possible addresses? Not feasible in fuzz. Use a synthetic invariant:
        // totalSupply = address(this).balance + sum(c.balances(x)) for all x holding balance.
        // But we cannot iterate. Instead, track via a state variable? Not allowed.
        // Alternative: Use a proxy contract that records every deposit/cashout? No.
        // Given constraints, we'll use a simple property: the caller's balance never increases after CashOut.
        // But that is already tried. Let's use: after CashOut, the contract's ether balance plus caller's balance <= previous value.
        // Tried: "After a call to CashOut, the caller's balance must not increase."
        // The bug causes caller's balance to increase, so that rule should work. Let's verify: 
        // In reference, balances[caller] decreases, contract balance decreases by _am. So caller's balance + contract balance decreases by 2*_am? No, caller's balance is internal, not ether. The call removes _am from contract and sends to caller. So caller's ether balance increases, but balances[caller] decreases. So not monotonic.
        // We need a new invariant.
        // Observing: The bug changes subtraction to addition, so balances[caller] increases instead of decreases. The contract's total supply? The sum of all balances plus contract ether equals total ether ever deposited (plus initial). Each CashOut should reduce total supply by _am (since we send _am to caller). Instead, buggy version increases balances[caller] by _am, so total supply increases by _am (since we add to balances) and contract ether decreases by _am, net zero? No, total sum balances goes up by _am, contract ether down by _am, net zero? Wait: initial total supply = sum balances + contract ether. After CashOut (caller, _am): reference: sum balances decreases by _am, contract ether decreases by _am, total decreases by 2*_am. Bug: sum balances increases by _am, contract ether decreases by _am, total unchanged. So after bug, total supply (sumBal + contractBal) is higher than reference after a successful CashOut. So we can compare before/after.
        // But we cannot read all balances. So we use a weaker but correct rule: The total supply never goes below a minimum computed from deposits. Hard.
        // Simpler: After two consecutive CashOut calls from the same caller, the caller's balance before the first call and after the second call must not increase (i.e., non-increasing across multiple calls). But the bug causes increase after one call, so this holds.
        // Actually, reference: balances[caller] decreases each time. Bug: increases. So after two calls, reference goes down, bug goes up. So we can test: after two CashOut calls, the caller's balance is less than or equal to its balance before the first call.
        // That works: bug will break.

        // Let's implement this.
        // Step 3: Read caller's balance before any CashOut
        uint256 balanceBeforeFirst = c.balances(caller);

        // Step 4: Perform first CashOut (if balance >= amount)
        vm.assume(caller.balance >= cashOut); // But the call sends ether, not needed; CashOut sends to caller from contract
        // Actually, we just call CashOut with _am. It might revert if _am > balances[caller]. To avoid revert, assume _am <= balances[caller]
        vm.assume(cashOut <= balanceBeforeFirst);

        vm.prank(caller);
        (bool ok1,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashOut));
        // If revert, skip? We only care about success paths.
        vm.assume(ok1);

        uint256 balanceAfterFirst = c.balances(caller);

        // Step 5: Second CashOut (with possibly different amount)
        uint256 cashOut2 = bound(cashOutAmt, 0, balanceAfterFirst);
        vm.prank(caller);
        (bool ok2,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashOut2));
        vm.assume(ok2);

        uint256 balanceAfterSecond = c.balances(caller);

        // Rule: balance after second call must be <= balance before first call
        assertTrue(balanceAfterSecond <= balanceBeforeFirst, "Balance increased over two CashOuts");
    }
}

